pub fn limit(
    flag: Option<&str>,
    environment: Option<&str>,
) -> Result<u16, String> {
    let raw = flag.or(environment).unwrap_or("20");
    match raw.parse::<u16>() {
        Ok(n) if (1..=100).contains(&n) => Ok(n),
        _ => Err("invalid limit".to_owned()),
    }
}

fn main() {
    assert_eq!(limit(Some("7"), Some("bad")), Ok(7), "case 1");
    assert_eq!(limit(None, None), Ok(20), "case 2");
    assert_eq!(limit(None, Some("100")), Ok(100), "case 3");
    assert_eq!(
        limit(Some(""), Some("5")),
        Err("invalid limit".to_owned()),
        "case 4"
    );
    assert_eq!(
        limit(Some("0"), None),
        Err("invalid limit".to_owned()),
        "case 5"
    );
    assert_eq!(
        limit(None, Some("101")),
        Err("invalid limit".to_owned()),
        "case 6"
    );
    println!("worked example passed");
}

